const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let toastTimer;
function notice(message,error=false){const el=$('#notice');el.textContent=message;el.classList.toggle('error',error);el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,error?12000:5000)}
window.addEventListener('unhandledrejection',e=>{console.error(e.reason);notice('Une erreur est survenue : '+(e.reason?.message||e.reason),true)});
const material=(color,roughness=.3,metalness=.15)=>new T.MeshPhysicalMaterial({color,roughness,metalness,clearcoat:.3,clearcoatRoughness:.2});
const mesh=(geo,color,rough=.3,metal=.15)=>{if(geo.type==='RoundedBoxGeometry'){const source=geo;geo=new T.BufferGeometry().copy(source);source.dispose()}const m=new T.Mesh(geo,material(color,rough,metal));m.castShadow=true;m.receiveShadow=true;return m};
function rounded(w,h,d,color,r=.1){return mesh(new RoundedBoxGeometry(w,h,d,3,r),color)}
function bottle(){const g=new T.Group();g.name='Flacon';const body=mesh(new T.CylinderGeometry(.58,.58,1.7,48), '#c7b4e0',.25,.05);body.position.y=.95;g.add(body);const shoulder=mesh(new T.SphereGeometry(.58,40,24),'#c7b4e0');shoulder.scale.y=.5;shoulder.position.y=1.8;g.add(shoulder);const neck=mesh(new T.CylinderGeometry(.26,.26,.35,32),'#c7b4e0');neck.position.y=2.02;g.add(neck);const cap=mesh(new T.CylinderGeometry(.29,.29,.3,32),'#292733',.24,.6);cap.position.y=2.25;g.add(cap);const label=mesh(new T.CylinderGeometry(.585,.585,.8,48),'#eee6f5',.7,0);label.position.y=.96;g.add(label);return g}
function phone(){const g=new T.Group();g.name='Smartphone';const body=rounded(1.15,2.3,.15,'#9d95b7',.12);g.add(body);const screen=rounded(1.05,2.18,.025,'#201c36',.1);screen.position.z=.087;g.add(screen);const visual=rounded(.96,1.98,.01,'#b78ce4',.08);visual.position.set(0,-.03,.104);g.add(visual);const ring=mesh(new T.TorusGeometry(.29,.08,16,64),'#d6c0ef',.24,.3);ring.position.set(0,.2,.13);g.add(ring);const camera=rounded(.32,.07,.02,'#15141c',.03);camera.position.set(0,.96,.12);g.add(camera);g.position.y=1.3;g.rotation.set(-.1,-.4,-.14);return g}
function pedestal(x=0,z=0){const m=mesh(new T.CylinderGeometry(1.22,1.22,.28,64),'#282630',.55,.05);m.position.set(x,.14,z);m.name='Socle';return m}
const models=[{id:'abstract',title:'Équilibre créatif',cat:'abstract',label:'ABSTRAIT',detail:'5 objets · 5,1 × 3,3 × 3 unités'}, {id:'bottle',title:'Essentiel cosmétique',cat:'packaging',label:'PACKAGING',detail:'3 objets · 3,6 × 2,7 × 3 unités'}, {id:'phone',title:'Nouvelle connexion',cat:'tech',label:'TECHNOLOGIE',detail:'2 objets · 2,5 × 2,9 × 2,5 unités'}, {id:'sculpture',title:'Matière libre',cat:'abstract',label:'ABSTRAIT',detail:'3 objets · 3,2 × 3,8 × 3,2 unités'}];
function makeTemplate(id){const g=new T.Group();
 if(id==='abstract'){const knot=mesh(new T.TorusKnotGeometry(.72,.24,150,24,2,3),'#b98bde',.25,.25);knot.name='Nœud créatif';knot.position.set(-.65,1.65,0);knot.rotation.set(.3,.2,-.35);g.add(knot);const sphere=mesh(new T.SphereGeometry(.54,48,32),'#83d9ff',.16,.65);sphere.name='Sphère';sphere.position.set(1.22,.83,.5);g.add(sphere);const ring=mesh(new T.TorusGeometry(.64,.14,24,80),'#c7c3d9',.16,.9);ring.name='Anneau';ring.position.set(1.12,1.88,-.4);ring.rotation.set(.5,.4,-.3);g.add(ring,pedestal(-.65),pedestal(1.15,.2));}
 else if(id==='bottle'){g.add(bottle(),pedestal());const ball=mesh(new T.SphereGeometry(.35,32,24),'#83d9ff',.2,.45);ball.position.set(1.15,.35,.4);ball.name='Sphère';g.add(ball)}
 else if(id==='phone'){g.add(phone(),pedestal())}
 else {const knot=mesh(new T.TorusKnotGeometry(.78,.24,180,24,3,4),'#83d9ff',.2,.6);knot.position.y=1.65;knot.rotation.z=.35;knot.name='Sculpture';g.add(knot,pedestal());const ring=mesh(new T.TorusGeometry(.65,.09,24,64),'#c28cff',.2,.7);ring.position.set(0,.36,0);ring.rotation.x=Math.PI/2;ring.name='Anneau';g.add(ring)}
 return g;
}
function makeStage(container,{hero=false}={}){const renderer=new T.WebGLRenderer({antialias:true,alpha:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.2;renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;container.append(renderer.domElement);renderer.domElement.setAttribute('aria-label',hero?'Démonstration 3D interactive':'Vue 3D de votre projet');const scene=new T.Scene();const camera=new T.PerspectiveCamera(36,1,.05,200);camera.position.set(hero?5:6,hero?3.8:4.5,hero?7:7);const orbit=new OrbitControls(camera,renderer.domElement);orbit.target.set(0,1.15,0);orbit.enableDamping=true;orbit.minDistance=1;orbit.maxDistance=45;orbit.maxPolarAngle=Math.PI*.91;const ambient=new T.HemisphereLight('#e7dcff','#51465d',2);scene.add(ambient);const key=new T.DirectionalLight('#fff3eb',4);key.position.set(4,7,5);key.castShadow=true;key.shadow.mapSize.set(2048,2048);key.shadow.camera.left=-10;key.shadow.camera.right=10;key.shadow.camera.top=10;key.shadow.camera.bottom=-10;key.shadow.bias=-.001;scene.add(key);const rim=new T.DirectionalLight('#a3caff',3);rim.position.set(-5,3,-3);scene.add(rim);const pmrem=new T.PMREMGenerator(renderer);const room=new RoomEnvironment();const environment=pmrem.fromScene(room).texture;scene.environment=environment;room.dispose();pmrem.dispose();const ground=new T.Mesh(new T.PlaneGeometry(100,100),new T.ShadowMaterial({opacity:.2}));ground.rotation.x=-Math.PI/2;ground.position.y=-.012;ground.receiveShadow=true;scene.add(ground);let active=true;const resize=()=>{const w=container.clientWidth,h=container.clientHeight;if(!w||!h)return;camera.aspect=w/h;camera.updateProjectionMatrix();renderer.setSize(w,h,false)};new ResizeObserver(resize).observe(container);resize();renderer.setAnimationLoop(()=>{if(!active||!container.clientWidth||!container.clientHeight||document.hidden)return;orbit.update();renderer.render(scene,camera)});renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();notice('Le contexte graphique a été interrompu. Rechargez la page pour restaurer la sauvegarde locale.',true)});return {renderer,scene,camera,orbit,key,rim,ambient,ground,resize,setActive:v=>active=v}}
let hero,stage,objects,transform,selection=null,db,tab='objects',isStudio=false,preview=false,busy=false;
let settings={background:'#17161e',light:'studio',intensity:4},past=[],future=[],saveTimer,historyBusy=false;
let projectName='Nouvelle perspective';
function theme(){let light=false;try{light=localStorage.getItem('nexo-theme')==='light'||localStorage.getItem('theme')==='light'}catch{}document.body.classList.toggle('light',light);}
theme();$$('[data-theme]').forEach(b=>b.onclick=()=>{document.body.classList.toggle('light');try{localStorage.setItem('nexo-theme',document.body.classList.contains('light')?'light':'dark')}catch{}});$('#back-top').onclick=()=>scrollTo({top:0,behavior:'smooth'});
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('mockxo-studio',1);r.onupgradeneeded=()=>r.result.createObjectStore('projects');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function dbGet(){return new Promise((resolve,reject)=>{const r=db.transaction('projects').objectStore('projects').get('current');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function dbPut(data){return new Promise((resolve,reject)=>{const tx=db.transaction('projects','readwrite');tx.objectStore('projects').put(data,'current');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
function snapshot(){return {format:'mockxo',version:1,name:projectName,settings:{...settings},camera:{position:stage.camera.position.toArray(),target:stage.orbit.target.toArray()},objects:objects.toJSON()}}
async function save(manual=false){if(!stage||historyBusy)return;clearTimeout(saveTimer);try{if(!db)throw Error('stockage indisponible');await dbPut(snapshot());$('#save-status').textContent='Sauvegardé sur cet appareil';if(manual)notice('Projet sauvegardé sur cet appareil.')}catch(e){$('#save-status').textContent='Sauvegarde indisponible';if(manual||!save.warned){notice('Sauvegarde locale impossible. Téléchargez une copie dans Projet pour conserver votre travail.',true);save.warned=true}}}
function scheduleSave(){if(!stage||historyBusy)return;$('#save-status').textContent='Modifications en cours…';clearTimeout(saveTimer);saveTimer=setTimeout(()=>save(),650)}
function pushHistory(){if(historyBusy)return;past.push(snapshot());if(past.length>20)past.shift();future=[];historyButtons()}
function historyButtons(){$('#undo').disabled=!past.length||historyBusy;$('#redo').disabled=!future.length||historyBusy}
function dispose(root){const gs=new Set(),ms=new Set(),ts=new Set();root.traverse(o=>{if(o.geometry)gs.add(o.geometry);for(const m of Array.isArray(o.material)?o.material:[o.material]){if(!m)continue;ms.add(m);for(const v of Object.values(m))if(v?.isTexture)ts.add(v)}});gs.forEach(g=>g.dispose());ms.forEach(m=>m.dispose());ts.forEach(t=>t.dispose())}
async function restore(data){if(data?.format!=='mockxo'||data.version!==1||!data.objects?.object||data.objects.object.type!=='Group')throw Error('Ce fichier n’est pas un projet Mockxo valide.');const loaded=await new T.ObjectLoader().parseAsync(data.objects);if(loaded.children.length>150){dispose(loaded);throw Error('Ce projet dépasse la limite de 150 objets.')}select(null);stage.scene.remove(objects);dispose(objects);objects=loaded;stage.scene.add(objects);projectName=String(data.name||'Sans titre').slice(0,80);$('#project-name').value=projectName;settings={background:'#17161e',light:'studio',intensity:4,...data.settings};applySettings();if(data.camera?.position?.length===3&&data.camera?.target?.length===3){stage.camera.position.fromArray(data.camera.position);stage.orbit.target.fromArray(data.camera.target);stage.orbit.update()}updateList();renderTool();select(objects.children.find(o=>o.visible)||null)}
async function undo(redo=false){if(historyBusy)return;const from=redo?future:past,to=redo?past:future;if(!from.length)return;const current=snapshot(),target=from.pop();historyBusy=true;historyButtons();try{await restore(target);to.push(current)}catch(e){from.push(target);notice(e.message,true)}finally{historyBusy=false;historyButtons();scheduleSave()}}
function applySettings(){if(!stage)return;const presets={studio:['#fff3eb','#a3caff',4,3],product:['#ffffff','#ffffff',5,2],sunset:['#ffbb87','#b28cff',4,3],soft:['#eeeaff','#b9e8ff',2.5,2]};const p=presets[settings.light]||presets.studio;stage.key.color.set(p[0]);stage.rim.color.set(p[1]);stage.key.intensity=Number(settings.intensity);stage.rim.intensity=p[3];stage.scene.background=null;$('#studio-canvas').style.background=settings.background}
function select(obj){selection=obj;transform?.detach();if(obj&&obj.visible&&!preview)transform.attach(obj);updateList();renderProperties();$('#selection-label').textContent=obj?obj.name:'Sélectionnez un objet'}
function updateList(){$('#object-count').textContent=objects?.children.length||0;if(!objects)return;$('#object-list').innerHTML=objects.children.map(o=>`<div class="object-row ${selection===o?'selected':''}"><button class="object-name" data-select="${o.uuid}">◈ &nbsp; ${escape(o.name)}</button><button class="visibility" data-visible="${o.uuid}" aria-label="${o.visible?'Masquer':'Afficher'} ${escape(o.name)}" title="${o.visible?'Masquer':'Afficher'}">${o.visible?'◉':'○'}</button></div>`).join('');$$('[data-select]').forEach(b=>b.onclick=()=>select(objects.getObjectByProperty('uuid',b.dataset.select)));$$('[data-visible]').forEach(b=>b.onclick=()=>{const obj=objects.getObjectByProperty('uuid',b.dataset.visible);pushHistory();obj.visible=!obj.visible;select(obj);scheduleSave()})}
function transformInputs(){const specs=[['position','Position',.1],['rotation','Rotation · °',5],['scale','Échelle',.1]];return specs.map(([key,label,step])=>`<div class="prop-label">${label}</div><div class="axis-inputs">${['x','y','z'].map(axis=>`<label>${axis.toUpperCase()}<input aria-label="${label} ${axis.toUpperCase()}" data-transform="${key}" data-axis="${axis}" type="number" step="${step}" ${key==='scale'?'min="0.01" max="100"':'min="-10000" max="10000"'} value="${(key==='rotation'?T.MathUtils.radToDeg(selection[key][axis]):selection[key][axis]).toFixed(2)}"></label>`).join('')}</div>`).join('')}
function firstMat(){let m;selection?.traverse(o=>{if(!m&&o.isMesh)m=Array.isArray(o.material)?o.material[0]:o.material});return m}
function changeMaterial(fn){if(!selection)return;selection.traverse(o=>{if(!o.isMesh)return;const mats=Array.isArray(o.material)?o.material:[o.material];mats.forEach(m=>{fn(m);m.needsUpdate=true})})}
function renderProperties(){const el=$('#properties');if(!selection){el.innerHTML='<div class="prop-empty"><span>◈</span>Une idée commence par une forme.<br>Sélectionnez un objet dans la scène pour le personnaliser.</div>';return}const m=firstMat();selection.updateWorldMatrix(true,true);const dim=new T.Box3().setFromObject(selection).getSize(new T.Vector3());el.innerHTML=`<section class="prop-section"><h3>OBJET SÉLECTIONNÉ</h3><input type="text" id="object-name" aria-label="Nom de l’objet" maxlength="60" value="${escape(selection.name)}"></section><section class="prop-section"><h3>TRANSFORMATIONS</h3>${transformInputs()}<p class="dimensions">DIMENSIONS<br>${dim.toArray().map(n=>n.toFixed(2)).join(' × ')} unités</p><button id="center-object" class="outline-btn wide">Centrer l’objet</button></section>${m?`<section class="prop-section"><h3>MATÉRIAU</h3><label class="prop-label">Couleur <input id="color" type="color" value="#${m.color?.getHexString()||'ffffff'}"></label><div class="swatches">${['#c28cff','#83d9ff','#f1f0ee','#292733','#e9b59a','#b4ccae'].map(c=>`<button class="swatch" style="background:${c}" data-color="${c}" aria-label="Couleur ${c}"></button>`).join('')}</div><div class="material-options">${['Satin','Métal','Verre','Céramique'].map(n=>`<button data-material="${n}">${n}</button>`).join('')}</div>${[['roughness','Rugosité',m.roughness??.5],['metalness','Métallicité',m.metalness??0],['opacity','Opacité',m.opacity??1]].map(([key,label,value])=>`<label class="prop-label" for="${key}">${label}<output id="${key}-value">${Math.round(value*100)} %</output></label><input type="range" id="${key}" min="0" max="1" step="0.01" value="${value}">`).join('')}<p class="help">Appliqué à toutes les surfaces de cet objet. Les textures importées sont conservées.</p></section>`:''}<section class="prop-section"><div class="object-actions"><button id="duplicate" class="outline-btn">Dupliquer</button><button id="delete" class="outline-btn danger">Supprimer</button></div></section>`;
$('#object-name').onchange=e=>{pushHistory();selection.name=e.target.value.trim()||'Objet';updateList();scheduleSave()};$$('[data-transform]').forEach(input=>input.onchange=()=>{const val=Number(input.value),key=input.dataset.transform,axis=input.dataset.axis;if(!Number.isFinite(val)||(key==='scale'&&(val<.01||val>100))||Math.abs(val)>10000){notice('Saisissez une valeur valide. L’échelle doit rester entre 0,01 et 100.',true);renderProperties();return}pushHistory();selection[key][axis]=key==='rotation'?T.MathUtils.degToRad(val):val;renderProperties();scheduleSave()});$('#center-object').onclick=()=>{pushHistory();const box=new T.Box3().setFromObject(selection);const center=box.getCenter(new T.Vector3());selection.position.x-=center.x;selection.position.z-=center.z;selection.position.y-=box.min.y;renderProperties();scheduleSave()};
if(m){const colorChange=color=>{changeMaterial(mat=>mat.color?.set(color));scheduleSave()};$('#color').addEventListener('pointerdown',()=>pushHistory());$('#color').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' ')pushHistory()});$('#color').oninput=e=>colorChange(e.target.value);$$('[data-color]').forEach(b=>b.onclick=()=>{pushHistory();colorChange(b.dataset.color);renderProperties()});$$('[data-material]').forEach(b=>b.onclick=()=>{pushHistory();const presets={'Satin':[.35,.05,1],'Métal':[.18,1,1],'Verre':[.08,0,.3],'Céramique':[.23,0,1]},p=presets[b.dataset.material];changeMaterial(mat=>{mat.roughness=p[0];mat.metalness=p[1];mat.opacity=p[2];mat.transparent=p[2]<1;mat.depthWrite=p[2]===1});renderProperties();scheduleSave()});['roughness','metalness','opacity'].forEach(key=>{const input=$('#'+key);input.onpointerdown=()=>pushHistory();input.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End','PageUp','PageDown'].includes(e.key))pushHistory()};input.oninput=()=>{const value=Number(input.value);changeMaterial(mat=>{mat[key]=value;if(key==='opacity'){mat.transparent=value<1;mat.depthWrite=value===1}});$('#'+key+'-value').textContent=Math.round(value*100)+' %';scheduleSave()}})}$('#duplicate').onclick=duplicate;$('#delete').onclick=removeSelected;
}
function duplicate(){if(!selection||!canAdd())return;pushHistory();const copy=selection.clone(true);copy.traverse(o=>{if(o.geometry)o.geometry=o.geometry.clone();if(o.material)o.material=Array.isArray(o.material)?o.material.map(m=>m.clone()):o.material.clone()});copy.position.x+=.65;copy.name=selection.name+' · copie';objects.add(copy);select(copy);scheduleSave()}
