function canAdd(){if(objects.children.length>=150){notice('La scène est limitée à 150 objets pour préserver les performances.',true);return false}return true}
const shapes=[['cube','Cube','◇'],['sphere','Sphère','◉'],['cylinder','Cylindre','▱'],['cone','Cône','△'],['torus','Tore','◎'],['plane','Plan','▰']];
function addShape(type){if(!canAdd())return;pushHistory();const geos={cube:()=>new RoundedBoxGeometry(1,1,1,3,.06),sphere:()=>new T.SphereGeometry(.6,40,28),cylinder:()=>new T.CylinderGeometry(.5,.5,1.2,40),cone:()=>new T.ConeGeometry(.6,1.3,40),torus:()=>new T.TorusGeometry(.55,.17,24,64),plane:()=>new T.PlaneGeometry(2,2)};const o=mesh(geos[type](),'#c28cff');o.name=shapes.find(s=>s[0]===type)[1];o.position.set((objects.children.length%3-1)*.5,.8,0);if(type==='plane'){o.rotation.x=-Math.PI/2;o.position.y=.01;o.material.side=T.DoubleSide}objects.add(o);select(o);scheduleSave()}
function renderTool(){if(!stage)return;$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));const el=$('#tool-content');if(tab==='objects'){el.innerHTML=`<p class="tool-intro">Un clic, une nouvelle possibilité.</p><div class="shapes">${shapes.map(([id,n,s])=>`<button class="shape" data-shape="${id}"><span>${s}</span>${n}</button>`).join('')}</div><button id="import-model" class="outline-btn wide">↑ Importer un modèle</button><p class="help">GLB ou GLTF + ressources · 50 Mo max.<br>Pas de compression Draco / KTX2.</p>`;$$('[data-shape]').forEach(b=>b.onclick=()=>addShape(b.dataset.shape));$('#import-model').onclick=()=>$('#model-file').click()}
if(tab==='models'){el.innerHTML='<p class="tool-intro">Des scènes à vous approprier. Remplace la scène actuelle.</p>'+models.map(m=>`<button class="preset-button" data-template="${m.id}">${m.title} ↗<small>${m.label} · Géométries originales<br>${m.detail}<br>Usage personnel et commercial</small></button>`).join('');$$('[data-template]').forEach(b=>b.onclick=()=>confirmTemplate(b.dataset.template))}
if(tab==='lights'){el.innerHTML=`<p class="tool-intro">La bonne lumière change tout.</p><label class="field-label">Ambiance<select id="light-preset">${[['studio','Studio'],['product','Produit'],['sunset','Cinématique'],['soft','Douce']].map(([v,n])=>`<option value="${v}" ${settings.light===v?'selected':''}>${n}</option>`).join('')}</select></label><label class="prop-label" for="light-intensity">Intensité <output id="light-output">${settings.intensity}</output></label><input id="light-intensity" type="range" min="0" max="10" step=".1" value="${settings.intensity}"><label class="field-label">Couleur du fond<input id="background" type="color" value="${settings.background}"></label><p class="help">L’environnement studio et les deux sources lumineuses éclairent votre scène en temps réel.</p><button id="front-view" class="outline-btn wide">Vue de face</button><button id="top-view" class="outline-btn wide">Vue de dessus</button><button id="perspective-view" class="outline-btn wide">Vue perspective</button>`;$('#light-preset').onchange=e=>{pushHistory();settings.light=e.target.value;settings.intensity={studio:4,product:5,sunset:4,soft:2.5}[settings.light];applySettings();renderTool();scheduleSave()};$('#light-intensity').onpointerdown=()=>pushHistory();$('#light-intensity').oninput=e=>{settings.intensity=Number(e.target.value);$('#light-output').textContent=settings.intensity;applySettings();scheduleSave()};$('#background').onpointerdown=()=>pushHistory();$('#background').oninput=e=>{settings.background=e.target.value;applySettings();scheduleSave()};$('#front-view').onclick=()=>setView([0,1.4,8]);$('#top-view').onclick=()=>setView([0,10,.01]);$('#perspective-view').onclick=()=>setView([6,4.5,7])}
if(tab==='project'){el.innerHTML='<p class="tool-intro">Vos idées restent sur cet appareil. Gardez aussi une copie indépendante.</p><button id="download-project" class="preset-button">↓ Télécharger le projet<small>Fichier .mockxo · objets et matériaux</small></button><button id="load-project" class="preset-button">↑ Ouvrir un projet<small>Restaurer un fichier .mockxo</small></button><button id="new-project" class="preset-button">+ Nouvelle scène<small>Repartir d’une scène vide</small></button><button id="project-save" class="outline-btn wide">Sauvegarder sur cet appareil</button><p class="help">Sauvegarde automatique après modification. Un projet actif par navigateur. Les 20 dernières modifications peuvent être annulées pendant cette session.</p>';$('#download-project').onclick=()=>download(new Blob([JSON.stringify(snapshot())],{type:'application/json'}),safeName()+'.mockxo');$('#load-project').onclick=()=>$('#project-file').click();$('#project-save').onclick=()=>save(true);$('#new-project').onclick=()=>confirmAction(()=>replaceTemplate(null))}}
$$('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;renderTool()});
function setView(position){stage.camera.position.fromArray(position);stage.orbit.target.set(0,1,0);stage.orbit.update();scheduleSave()}
function frameScene(){const box=new T.Box3().setFromObject(objects);if(box.isEmpty()){setView([6,4.5,7]);return}const center=box.getCenter(new T.Vector3()),size=box.getSize(new T.Vector3()).length();stage.orbit.target.copy(center);const distance=Math.max(size,2)*1.3;stage.camera.position.copy(center).add(new T.Vector3(1,.65,1.35).normalize().multiplyScalar(distance));stage.camera.far=Math.max(200,size*10);stage.camera.updateProjectionMatrix();stage.orbit.update();scheduleSave()}
let pendingConfirm;
function confirmAction(fn){pendingConfirm=fn;$('#confirm-dialog').showModal()}
$('#confirm-cancel').onclick=()=>{$('#confirm-dialog').close();pendingConfirm=null};$('#confirm-ok').onclick=()=>{$('#confirm-dialog').close();pendingConfirm?.();pendingConfirm=null};
function confirmTemplate(id){if(objects.children.length)confirmAction(()=>replaceTemplate(id));else replaceTemplate(id)}
function replaceTemplate(id){pushHistory();select(null);for(const o of [...objects.children]){objects.remove(o);dispose(o)}if(id){const group=makeTemplate(id);for(const o of [...group.children])objects.add(o);projectName=models.find(m=>m.id===id).title}else projectName='Nouvelle scène';$('#project-name').value=projectName;select(objects.children[0]||null);frameScene();scheduleSave()}
function safeName(){return projectName.replace(/[^a-zA-Z0-9À-ÿ_-]+/g,'-').slice(0,60)||'mockxo'}
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000)}
function togglePreview(force){preview=typeof force==='boolean'?force:!preview;$('.viewport-wrap').classList.toggle('previewing',preview);transform.detach();stage.grid.visible=!preview&&stage.showGrid;let exit=$('.preview-exit');if(preview){exit=document.createElement('button');exit.className='preview-exit outline-btn';exit.textContent='Quitter la prévisualisation · Échap';exit.onclick=()=>togglePreview(false);$('.viewport-wrap').append(exit)}else{exit?.remove();if(selection?.visible)transform.attach(selection)}}
$('#preview').onclick=()=>togglePreview();$('#frame').onclick=frameScene;$('#grid-toggle').onclick=()=>{stage.showGrid=!stage.showGrid;stage.grid.visible=stage.showGrid;$('#grid-toggle').classList.toggle('active',stage.showGrid)};
function setMode(mode){transform.setMode(mode);$$('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode))}$$('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));
$('#undo').onclick=()=>undo();$('#redo').onclick=()=>undo(true);$('#save').onclick=()=>save(true);$('#project-name').onchange=e=>{pushHistory();projectName=e.target.value.trim()||'Sans titre';e.target.value=projectName;scheduleSave()};$('#guide-open').onclick=()=>$('#guide-dialog').showModal();$('#export-open').onclick=()=>$('#export-dialog').showModal();
$('#export-png').onclick=async()=>{if(busy)return;busy=true;const button=$('#export-png');button.disabled=true;button.textContent='Rendu en cours…';const renderer=stage.renderer,originalSize=renderer.getSize(new T.Vector2()),pixelRatio=renderer.getPixelRatio(),oldBg=stage.scene.background,gridVisible=stage.grid.visible,helperVisible=transform.getHelper().visible;stage.setActive(false);try{await new Promise(r=>requestAnimationFrame(r));const [w,h]=$('#export-size').value.split(',').map(Number);if(w>renderer.capabilities.maxTextureSize||h>renderer.capabilities.maxTextureSize)throw Error('Cette résolution dépasse les capacités de cet appareil. Choisissez une résolution inférieure.');renderer.setPixelRatio(1);renderer.setSize(w,h,false);const camera=stage.camera.clone();camera.aspect=w/h;camera.updateProjectionMatrix();stage.grid.visible=false;transform.getHelper().visible=false;stage.scene.background=$('#transparent').checked?null:new T.Color(settings.background);renderer.render(stage.scene,camera);const blob=await new Promise(r=>renderer.domElement.toBlob(r,'image/png'));if(!blob)throw Error('Le navigateur ne peut pas générer cette image. Essayez une résolution inférieure.');download(blob,safeName()+'.png');notice(`Image PNG exportée · ${w} × ${h}`);$('#export-dialog').close()}catch(e){notice('Export impossible : '+e.message,true)}finally{stage.grid.visible=gridVisible;transform.getHelper().visible=helperVisible;stage.scene.background=oldBg;renderer.setPixelRatio(pixelRatio);renderer.setSize(originalSize.x,originalSize.y,false);stage.resize();stage.setActive(isStudio);busy=false;button.disabled=false;button.textContent='Télécharger le PNG ↗'}};
$('#model-file').onchange=async e=>{const files=[...e.target.files];e.target.value='';if(!files.length||!canAdd())return;const root=files.find(f=>/\.(glb|gltf)$/i.test(f.name));if(!root){notice('Sélectionnez un fichier GLB ou GLTF avec ses ressources.',true);return}if(files.reduce((a,f)=>a+f.size,0)>50*1024*1024){notice('L’import est limité à 50 Mo par sélection.',true);return}notice('Import du modèle…');const urls=new Map();for(const f of files)urls.set(f.name,URL.createObjectURL(f));const manager=new T.LoadingManager();manager.setURLModifier(url=>{if(url.startsWith('blob:')||url.startsWith('data:'))return url;const name=decodeURIComponent(url.split('/').pop());if(!urls.has(name))throw Error('Ressource manquante : '+name+'. Sélectionnez le GLTF, ses fichiers .bin et ses textures ensemble.');return urls.get(name)});try{const gltf=await new GLTFLoader(manager).parseAsync(await root.arrayBuffer(),'');const group=gltf.scene;group.name=root.name.replace(/\.(glb|gltf)$/i,'');let count=0;group.traverse(o=>{if(o.isMesh){count+=(o.geometry.index?.count||o.geometry.attributes.position?.count||0)/3;o.castShadow=true;o.receiveShadow=true}});if(count>600000){dispose(group);throw Error('Modèle trop complexe : limite de 600 000 triangles. Simplifiez le modèle avant de réessayer.')}const box=new T.Box3().setFromObject(group),size=box.getSize(new T.Vector3()),max=Math.max(size.x,size.y,size.z);if(!Number.isFinite(max)||max<=0){dispose(group);throw Error('Le modèle ne contient aucune géométrie visible.')}const wrapper=new T.Group();wrapper.name=group.name;wrapper.add(group);group.scale.multiplyScalar(2.5/max);const bounds=new T.Box3().setFromObject(group),center=bounds.getCenter(new T.Vector3());group.position.sub(new T.Vector3(center.x,bounds.min.y,center.z));pushHistory();objects.add(wrapper);select(wrapper);frameScene();scheduleSave();notice('Modèle importé · '+Math.round(count).toLocaleString('fr-FR')+' triangles.')}catch(err){notice('Import impossible : '+err.message,true)}finally{urls.forEach(u=>URL.revokeObjectURL(u))}};
$('#project-file').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>100*1024*1024){notice('Ce projet dépasse la limite de 100 Mo.',true);return}let data;try{data=JSON.parse(await f.text());if(data?.format!=='mockxo'||data.version!==1)throw Error('Format non reconnu.')}catch(err){notice('Projet invalide : '+err.message,true);return}confirmAction(async()=>{pushHistory();try{await restore(data);scheduleSave();notice('Projet restauré.')}catch(err){notice('Ouverture impossible : '+err.message,true)}})};
window.addEventListener('keydown',e=>{if(!isStudio)return;const editing=/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName);if(e.key==='Escape'&&preview)togglePreview(false);if($$('dialog[open]').length||editing)return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey);return}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'){e.preventDefault();save(true);return}if(e.metaKey||e.ctrlKey||e.altKey)return;if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();removeSelected()}const modes={g:'translate',r:'rotate',s:'scale'};if(modes[e.key.toLowerCase()])setMode(modes[e.key.toLowerCase()])});
async function initStudio(){stage=makeStage($('#studio-canvas'));objects=new T.Group();objects.name='Scène Mockxo';stage.scene.add(objects);transform=new TransformControls(stage.camera,stage.renderer.domElement);stage.scene.add(transform.getHelper());transform.setSize(.85);transform.addEventListener('dragging-changed',e=>{stage.orbit.enabled=!e.value;if(e.value)pushHistory();else{renderProperties();scheduleSave()}});transform.addEventListener('objectChange',()=>{if(selection)$('#selection-label').textContent=selection.name});stage.grid=new T.GridHelper(20,40,'#51425d','#292630');stage.grid.position.y=-.02;stage.showGrid=true;stage.scene.add(stage.grid);let down;stage.renderer.domElement.addEventListener('pointerdown',e=>down={x:e.clientX,y:e.clientY});stage.renderer.domElement.addEventListener('pointerup',e=>{if(!down||Math.hypot(e.clientX-down.x,e.clientY-down.y)>4||transform.dragging||transform.axis||e.button!==0||preview)return;const rect=stage.renderer.domElement.getBoundingClientRect(),pointer=new T.Vector2((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1),ray=new T.Raycaster();ray.setFromCamera(pointer,stage.camera);const hit=ray.intersectObjects(objects.children,true).find(h=>{let o=h.object;while(o&&o!==objects){if(!o.visible)return false;o=o.parent}return true});let selected=hit?.object;while(selected&&selected.parent!==objects)selected=selected.parent;select(selected||null)});stage.orbit.addEventListener('end',scheduleSave);try{db=await openDB();const saved=await dbGet();if(saved){await restore(saved);notice('Votre dernière scène a été restaurée.')}else{const template=makeTemplate('abstract');for(const o of [...template.children])objects.add(o)}}catch(e){notice('La sauvegarde locale n’est pas disponible ou le dernier projet est illisible. Téléchargez une copie depuis Projet.',true);if(!objects.children.length){const group=makeTemplate('abstract');for(const o of [...group.children])objects.add(o)}}applySettings();renderTool();select(objects.children[0]||null);historyButtons();let seen=false;try{seen=localStorage.getItem('mockxo-guide')==='seen';localStorage.setItem('mockxo-guide','seen')}catch{}if(!seen)$('#guide-dialog').showModal();}
let routing=false;
async function route(){if(routing)return;routing=true;try{isStudio=location.hash==='#studio';$('#home').hidden=isStudio;$('#studio').hidden=!isStudio;document.body.classList.toggle('in-studio',isStudio);document.title=isStudio?'Studio 3D — Mockxo par NEXO':'Mockxo — La création 3D, tout simplement.';if(isStudio&&!stage)await initStudio();hero?.setActive(!isStudio);stage?.setActive(isStudio);if(isStudio)requestAnimationFrame(()=>stage.resize());else if(hero)requestAnimationFrame(()=>hero.resize())}catch(e){notice('Le rendu 3D ne peut pas démarrer sur cet appareil. Vérifiez que WebGL est activé. '+e.message,true)}finally{routing=false}}
window.addEventListener('hashchange',route);
let category='all';
function filterModels(){const term=$('#model-search').value.toLocaleLowerCase('fr-FR');let count=0;$$('.model-card').forEach(card=>{const model=models.find(m=>m.id===card.dataset.model);const match=(category==='all'||model.cat===category)&&(model.title+' '+model.label).toLocaleLowerCase('fr-FR').includes(term);card.hidden=!match;if(match)count++});$('#empty-models').hidden=!!count}
function renderModels(){ $('#model-grid').innerHTML=models.map(m=>`<button class="model-card" data-model="${m.id}"><span class="model-visual"><img alt="Aperçu rendu de ${m.title}" id="thumb-${m.id}"><span class="badge">${m.label}</span></span><span class="model-info"><strong>${m.title} <span>↗</span></strong><small>${m.detail}<br>Scène native · Complexité faible</small></span></button>`).join('');$$('[data-model]').forEach(b=>b.onclick=async()=>{location.hash='studio';await new Promise(resolve=>{const timer=setInterval(()=>{if(stage&&objects&&!routing){clearInterval(timer);resolve()}},50);setTimeout(()=>{clearInterval(timer);resolve()},10000)});if(stage&&objects)confirmTemplate(b.dataset.model)});$$('[data-filter]').forEach(b=>b.onclick=()=>{category=b.dataset.filter;$$('[data-filter]').forEach(n=>n.classList.toggle('active',n===b));filterModels()});$('#model-search').oninput=filterModels;filterModels();}
renderModels();
try{hero=makeStage($('#hero-canvas'),{hero:true});const composition=makeTemplate('abstract');hero.scene.add(composition);hero.orbit.enableZoom=false;hero.orbit.enablePan=false;$('#hero-reset').onclick=()=>{hero.camera.position.set(5,3.8,7);hero.orbit.target.set(0,1.15,0);hero.orbit.update()};const originalSize=new T.Vector2();hero.renderer.getSize(originalSize);hero.renderer.setSize(440,330,false);const originalAspect=hero.camera.aspect;hero.camera.aspect=440/330;hero.camera.updateProjectionMatrix();hero.scene.remove(composition);for(const model of models){const group=makeTemplate(model.id);group.updateWorldMatrix(true,true);const dimensions=new T.Box3().setFromObject(group).getSize(new T.Vector3());let triangles=0;group.traverse(o=>{if(o.isMesh)triangles+=(o.geometry.index?.count||o.geometry.attributes.position?.count||0)/3});model.detail=group.children.length+' objets · '+dimensions.toArray().map(n=>n.toLocaleString('fr-FR',{maximumFractionDigits:1})).join(' × ')+' unités';const meta=$('[data-model="'+model.id+'"] .model-info small');meta.textContent=model.detail;meta.append(document.createElement('br'),document.createTextNode('Scène native · '+Math.round(triangles).toLocaleString('fr-FR')+' triangles'));hero.scene.add(group);hero.renderer.render(hero.scene,hero.camera);$('#thumb-'+model.id).src=hero.renderer.domElement.toDataURL('image/png');hero.scene.remove(group);dispose(group)}hero.scene.add(composition);hero.camera.aspect=originalAspect;hero.camera.updateProjectionMatrix();hero.resize()}catch(e){notice('La démonstration 3D nécessite WebGL. '+e.message,true)}
route();
